```{ojs}
arm = {
  const r = Math.PI / 180, a1 = q1 * r, a12 = (q1 + q2) * r;
  const elbow = [cs.l1 * Math.cos(a1), cs.l1 * Math.sin(a1)];
  const hand = [elbow[0] + cs.l2 * Math.cos(a12), elbow[1] + cs.l2 * Math.sin(a12)];
  // Distance from the obstacle centre to a segment a-b.
  const dist = (a, b) => {
    const [cx, cy] = cs.obstacle, abx = b[0] - a[0], aby = b[1] - a[1];
    const t = Math.max(0, Math.min(1, ((cx - a[0]) * abx + (cy - a[1]) * aby) / (abx * abx + aby * aby)));
    return Math.hypot(cx - a[0] - t * abx, cy - a[1] - t * aby);
  };
  const hit = dist([0, 0], elbow) < cs.obstacle[2] || dist(elbow, hand) < cs.obstacle[2];
  return {elbow, hand, hit};
}
blockedCells = {
  const cell = 360 / cs.n, out = [];
  cs.blocked.forEach((row, i) => { for (let j = 0; j < cs.n; j++) if (row[j] === "1")
    out.push({x1: -180 + i * cell, x2: -180 + (i + 1) * cell, y1: -180 + j * cell, y2: -180 + (j + 1) * cell}); });
  return out;
}
```

